"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef, useState, useSyncExternalStore } from "react";

const REDUCED_MOTION = "(prefers-reduced-motion: reduce)";
const subscribeReducedMotion = (onChange: () => void) => {
  const mq = window.matchMedia(REDUCED_MOTION);
  mq.addEventListener("change", onChange);
  return () => mq.removeEventListener("change", onChange);
};
/** The visitor's reduced-motion preference; false while server-rendering. */
const useReducedMotion = () =>
  useSyncExternalStore(
    subscribeReducedMotion,
    () => window.matchMedia(REDUCED_MOTION).matches,
    () => false,
  );

const TRANSITION_MS = 300;
const MARK_WIDTH = 28;
const GAP = 12;

export interface TimelineCheckpoint {
  id: string;
  label: string;
  sublabel?: string;
  role?: "user" | "assistant" | "system";
}

export interface ConversationTimelineProps {
  checkpoints: TimelineCheckpoint[];
  activeId?: string;
  onSelect?: (id: string) => void;
  /** Which side the text sits — "right" (default) or "left". */
  side?: "left" | "right";
  /** Per-row height once expanded (hovering / focusing the rail), in px. Default 24. */
  rowHeight?: number;
  /** Per-row height at rest — just the marks, tightly packed. Default 10. */
  collapsedRowHeight?: number;
  /** Rows visible before scrolling. Height = visibleCount * rowHeight. Default 10. */
  visibleCount?: number;
  /** Fixed label column width (px) — labels truncate past this. Default 240. */
  labelWidth?: number;
  /**
   * Render the label column. Turn it off where width is tight — beside a chat
   * on a phone — and the rail becomes a marks-only minimap: the messages it
   * points at already carry the text. Marks keep their `aria-label`. Default true.
   */
  showLabels?: boolean;
  /** Accent colour for the active row's line. Defaults to the theme's primary. */
  accent?: string;
  className?: string;
}

/**
 * A dense rail of thin marks, one per message. Hover or focus expands it into
 * the full labelled list: rows grow to `rowHeight` and labels fade in. The row
 * under the cursor gets extra emphasis on top of that. `visibleCount` rows are
 * shown at once and the rest scroll.
 */
export function ConversationTimeline({
  checkpoints,
  activeId,
  onSelect,
  side = "right",
  rowHeight = 24,
  collapsedRowHeight = 10,
  visibleCount = 10,
  labelWidth = 240,
  showLabels = true,
  accent = "var(--primary)",
  className,
}: ConversationTimelineProps) {
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [expanded, setExpanded] = useState(false);
  const reduce = useReducedMotion();
  const isRight = side === "right";

  // Rows resize from 10px to 24px while scrolled, so the same scrollTop would
  // point at a different row. Anchor to the row element at the top and read
  // its live `offsetTop` instead of computing one from an assumed row height,
  // which would fight the in-progress transition.
  const containerRef = useRef<HTMLDivElement>(null);
  const rowRefs = useRef<(HTMLButtonElement | null)[]>([]);
  const anchorIndexRef = useRef(0);
  const captureScrollAnchor = () => {
    const el = containerRef.current;
    if (!el) return;
    const idx = rowRefs.current.findIndex(
      (row) => row && row.offsetTop + row.offsetHeight > el.scrollTop,
    );
    anchorIndexRef.current = idx < 0 ? 0 : idx;
  };
  useEffect(() => {
    const el = containerRef.current;
    const anchor = rowRefs.current[anchorIndexRef.current];
    if (!el || !anchor) return;
    const apply = () => {
      el.scrollTop = anchor.offsetTop;
    };
    apply();
    if (reduce) return;
    // Re-applied every frame for the transition's duration. The anchor's
    // offsetTop moves a little each frame, so re-reading it keeps the view
    // tracking rather than jumping once at the end.
    let raf = 0;
    const deadline = performance.now() + TRANSITION_MS + 50;
    const tick = () => {
      apply();
      if (performance.now() < deadline) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expanded]);

  // Touch has no hover, so stay expanded and keep the labels reachable.
  useEffect(() => {
    const mq = window.matchMedia("(hover: none)");
    setExpanded(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setExpanded(e.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  // Height is the only animated dimension. Gap and width stay fixed so the
  // rail never resizes horizontally and only one property drives layout.
  const transition = reduce
    ? "none"
    : `height ${TRANSITION_MS}ms var(--ease-smooth, cubic-bezier(0.4, 0, 0.2, 1))`;
  // +4px absorbs the hover nudge's translateX so it never clips against the
  // rail's own overflow-x boundary.
  const railWidth = MARK_WIDTH + 4 + (showLabels ? GAP + labelWidth : 0);
  // With the scrollbar hidden there's no native cue that a taller list
  // continues past view — fade the top/bottom edges as the affordance, but
  // only when there's actually more to scroll to.
  const isScrollable = checkpoints.length > visibleCount;
  const edgeFade = isScrollable
    ? "linear-gradient(to bottom, transparent, black 12px, black calc(100% - 12px), transparent)"
    : undefined;

  return (
    <div
      ref={containerRef}
      className={cn(
        "[scrollbar-width:none] [&::-webkit-scrollbar]:hidden [&::-webkit-scrollbar]:w-0 [&::-webkit-scrollbar]:h-0 relative flex flex-col overflow-y-auto overflow-x-hidden",
        className,
      )}
      style={{
        width: railWidth,
        maxHeight: visibleCount * (expanded ? rowHeight : collapsedRowHeight),
        transition,
        // Native scroll anchoring doesn't handle this case (every row resizes
        // at once) and otherwise fights our own re-anchoring above.
        overflowAnchor: "none",
        WebkitMaskImage: edgeFade,
        maskImage: edgeFade,
      }}
      onMouseEnter={() => {
        captureScrollAnchor();
        setExpanded(true);
      }}
      onMouseLeave={() => {
        captureScrollAnchor();
        setExpanded(false);
        setHoveredId(null);
      }}
      onFocus={() => {
        captureScrollAnchor();
        setExpanded(true);
      }}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) {
          captureScrollAnchor();
          setExpanded(false);
        }
      }}
    >
      {checkpoints.map((cp, i) => {
        const isActive = cp.id === activeId;
        const isHovered = cp.id === hoveredId;

        return (
          <button
            key={cp.id}
            ref={(el) => {
              rowRefs.current[i] = el;
            }}
            type="button"
            onMouseEnter={() => setHoveredId(cp.id)}
            onMouseLeave={() => setHoveredId(null)}
            onClick={() => onSelect?.(cp.id)}
            aria-label={cp.label}
            aria-current={isActive || undefined}
            className={cn(
              "group flex items-center outline-none cursor-pointer shrink-0 active:scale-[0.96] transition-transform",
              "focus-visible:outline-2 focus-visible:outline-offset-2",
              "focus-visible:outline-ring",
              isRight ? "flex-row" : "flex-row-reverse",
            )}
            style={{
              height: expanded ? rowHeight : collapsedRowHeight,
              gap: GAP,
              transition,
            }}
          >
            {/* the mark — fixed length, never moves. Standout comes from
                colour and opacity, not width, so the line stays put on hover. */}
            <span
              className="shrink-0 rounded-full transition-[opacity,background-color] duration-150 ease-out"
              style={{
                height: 2,
                width: MARK_WIDTH,
                background: isActive ? accent : "currentColor",
                opacity: isActive ? 1 : isHovered ? 0.8 : 0.28,
              }}
            />

            {/* the label — invisible at rest (the collapsed row has no room
                for it anyway), fades in once the rail expands. Font-weight
                stays constant (active = medium, rest = normal) so it never
                changes layout width; hover emphasis is colour + a
                post-layout transform only, so it can never nudge the marks. */}
            {showLabels && (
              <span
                className={cn(
                  "min-w-0 whitespace-nowrap tracking-[-0.01em] truncate",
                  isRight ? "text-left origin-left" : "text-right origin-right",
                  isActive ? "font-medium" : "font-normal",
                  isHovered
                    ? "text-foreground"
                    : isActive
                      ? "text-foreground/90"
                      : "text-muted-foreground",
                )}
                style={{
                  width: labelWidth,
                  fontSize: 13,
                  opacity: expanded ? 1 : 0,
                  // Nudge only — no scale. Scaling a truncated, fixed-width,
                  // edge-clipped label grows its rendered footprint past the
                  // rail's own clip boundary and cuts off the ellipsis itself.
                  transform: `translateX(${isHovered ? (isRight ? 3 : -3) : 0}px)`,
                  // Opacity rides the same pace as the row's expand/collapse
                  // (it's part of that motion); colour and the hover nudge are
                  // a separate, snappier per-row response — one shared
                  // duration for both made the hover feel sluggish.
                  transition: reduce
                    ? "none"
                    : `opacity ${TRANSITION_MS}ms var(--ease-smooth, cubic-bezier(0.4, 0, 0.2, 1)), color 150ms ease-out, transform 150ms ease-out`,
                }}
              >
                {cp.label}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}
